use vstd::prelude::*;

verus! {
    // Given a one‐dimensional Vec of f32, return a two‐dimensional Vec
    // with exactly one row, preserving the contents and order.
    fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
        ensures
            // exactly one row
            result.len() == 1,
            // that row is exactly the original array
            result[0] == arr
    {
        // construct an empty outer Vec
        let mut result: Vec<Vec<f32>> = Vec::new();
        // push the entire input Vec as the single row
        result.push(arr);
        result
    }
}

